dashboard.definition:
{
  "title": "Geography",
  "description": "Privacy-masked cells count activity visits, not GPS samples. Endpoint buffers and exported privacy zones are applied before indexing. The table remains usable without a basemap.",
  "visualizations": {
    "viz_0": {
      "type": "splunk.map",
      "title": "Personal activity visits",
      "dataSources": {
        "primary": "ds_0"
      },
      "options": {
        "layers": [
          {
            "type": "bubble",
            "latitude": "> primary | seriesByName(\"latitude\")",
            "longitude": "> primary | seriesByName(\"longitude\")",
            "bubbleSize": "> primary | seriesByName(\"visits\")"
          }
        ]
      },
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_1": {
      "type": "splunk.table",
      "title": "Visited cells (one visit per activity and cell)",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    },
    "viz_2": {
      "type": "splunk.bar",
      "title": "Geography coverage by sport",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {},
      "showProgressBar": true,
      "showLastUpdated": true
    }
  },
  "dataSources": {
    "ds_0": {
      "type": "ds.search",
      "name": "Personal activity visits",
      "options": {
        "query": "index=training_lens_shared sourcetype=training_lens:geography earliest=0 latest=+10y [ search index=training_lens sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=training_lens sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND stream_revision_id!=\"\" | fields stream_revision_id | appendpipe [ stats count | where count=0 | eval stream_revision_id=\"__none__\" ] | fields stream_revision_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | stats sum(visits) AS visits BY latitude longitude | sort 0 - visits | head 1000",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "ds_1": {
      "type": "ds.search",
      "name": "Visited cells (one visit per activity and cell)",
      "options": {
        "query": "index=training_lens_shared sourcetype=training_lens:geography earliest=0 latest=+10y [ search index=training_lens sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=training_lens sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND stream_revision_id!=\"\" | fields stream_revision_id | appendpipe [ stats count | where count=0 | eval stream_revision_id=\"__none__\" ] | fields stream_revision_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | stats sum(visits) AS visits dc(activity_id) AS activities BY latitude longitude | sort 0 - visits | head 1000",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Geography coverage by sport",
      "options": {
        "query": "index=training_lens_shared sourcetype=training_lens:geography earliest=0 latest=+10y [ search index=training_lens sourcetype=training_lens:activity earliest=0 latest=+10y [ search index=training_lens sourcetype=training_lens:ready earliest=0 latest=+10y | where $snapshot|s$=\"latest\" OR snapshot_id=$snapshot|s$ | sort 0 - import_epoch | head 1 | stats count AS selection_count first(snapshot_id) AS snapshot_id | eval snapshot_id=coalesce(snapshot_id,\"__none__\") | fields snapshot_id ] | dedup event_id | where ($sport|s$=\"All\" OR sport=$sport|s$) AND ($gear|s$=\"All\" OR gear=$gear|s$) AND stream_revision_id!=\"\" | fields stream_revision_id | appendpipe [ stats count | where count=0 | eval stream_revision_id=\"__none__\" ] | fields stream_revision_id ] | dedup event_id | where timestamp>=if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.earliest|s$,\"0\")),relative_time(now(),if((match($time.earliest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.earliest|s$=\"now\"),\"+0s\",$time.earliest|s$))) AND timestamp<=if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),tonumber(if(match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\"),$time.latest|s$,\"0\")),relative_time(now(),if((match($time.latest|s$,\"^[0-9]+([.][0-9]+)?$\") OR $time.latest|s$=\"now\"),\"+0s\",$time.latest|s$))) | stats dc(activity_id) AS mapped_activities BY sport",
        "queryParameters": {
          "earliest": "0",
          "latest": "+10y"
        }
      }
    }
  },
  "inputs": {
    "time": {
      "type": "input.timerange",
      "title": "Period",
      "options": {
        "token": "time",
        "defaultValue": "-1y,now"
      }
    },
    "sport": {
      "type": "input.dropdown",
      "title": "Sport",
      "options": {
        "token": "sport",
        "defaultValue": "All",
        "items": [
          {
            "label": "All",
            "value": "All"
          },
          {
            "label": "Run",
            "value": "Run"
          },
          {
            "label": "Ride",
            "value": "Ride"
          },
          {
            "label": "Hike",
            "value": "Hike"
          },
          {
            "label": "Alpine Ski",
            "value": "Alpine Ski"
          },
          {
            "label": "Weight Training",
            "value": "Weight Training"
          },
          {
            "label": "Workout",
            "value": "Workout"
          },
          {
            "label": "Walk",
            "value": "Walk"
          },
          {
            "label": "Swim",
            "value": "Swim"
          },
          {
            "label": "Nordic Ski",
            "value": "Nordic Ski"
          },
          {
            "label": "Backcountry Ski",
            "value": "Backcountry Ski"
          },
          {
            "label": "Kayaking",
            "value": "Kayaking"
          }
        ]
      }
    },
    "gear": {
      "type": "input.text",
      "title": "Gear (exact name or All)",
      "options": {
        "token": "gear",
        "defaultValue": "All"
      }
    },
    "quality": {
      "type": "input.dropdown",
      "title": "Quality",
      "options": {
        "token": "quality_mode",
        "defaultValue": "Validated",
        "items": [
          {
            "label": "Validated",
            "value": "Validated"
          },
          {
            "label": "Reported",
            "value": "Reported"
          },
          {
            "label": "Flagged only",
            "value": "Flagged only"
          }
        ]
      }
    },
    "units": {
      "type": "input.dropdown",
      "title": "Units",
      "options": {
        "token": "units",
        "defaultValue": "Metric",
        "items": [
          {
            "label": "Metric",
            "value": "Metric"
          },
          {
            "label": "Imperial",
            "value": "Imperial"
          }
        ]
      }
    },
    "snapshot": {
      "type": "input.text",
      "title": "Snapshot (latest or ID)",
      "options": {
        "token": "snapshot",
        "defaultValue": "latest"
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {},
    "structure": [
      {
        "item": "viz_0",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1200,
          "h": 300
        }
      },
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 300,
          "w": 1200,
          "h": 300
        }
      },
      {
        "item": "viz_2",
        "type": "block",
        "position": {
          "x": 0,
          "y": 600,
          "w": 1200,
          "h": 300
        }
      }
    ],
    "globalInputs": [
      "time",
      "sport",
      "gear",
      "quality",
      "units",
      "snapshot"
    ]
  }
}
